{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "用例 02 · 订单与深层嵌套",
  "description": "对象套对象、对象套数组、数组套对象；订单、明细、规格、价格与收货信息的多级结构。",
  "type": "object",
  "properties": {
    "orderNo": { "type": "string", "description": "订单编号。" },
    "status": { "type": "string", "enum": ["created", "paid", "shipped"], "description": "订单状态。" },
    "customer": {
      "type": "object", "description": "买家；必填依据 customer 自己的 required。",
      "properties": {
        "id": { "type": "string", "description": "买家 ID。" },
        "profile": {
          "type": "object", "properties": {
            "displayName": { "type": "string" },
            "preferences": { "type": "object", "properties": { "smsEnabled": { "type": "boolean" }, "languages": { "type": "array", "items": { "type": "string" } } }, "required": ["smsEnabled"] }
          }, "required": ["displayName"]
        }
      }, "required": ["id"]
    },
    "items": {
      "type": "array", "description": "订单明细；展开数组元素后查看字段。", "minItems": 1,
      "items": {
        "type": "object", "properties": {
          "lineId": { "type": "string" },
          "product": {
            "type": "object", "properties": {
              "sku": { "type": "string" },
              "attributes": { "type": "array", "items": { "type": "object", "properties": { "name": { "type": "string" }, "values": { "type": "array", "items": { "type": "string" } } }, "required": ["name", "values"] } }
            }, "required": ["sku"]
          },
          "quantity": { "type": "integer", "minimum": 1 },
          "unitPrice": { "type": "object", "properties": { "amount": { "type": "number", "minimum": 0 }, "currency": { "type": "string", "enum": ["CNY", "USD", "EUR"] } }, "required": ["amount", "currency"] },
          "gift": { "type": "boolean", "default": false }
        }, "required": ["lineId", "product", "quantity", "unitPrice"]
      }
    },
    "delivery": {
      "type": "object", "properties": {
        "address": { "type": "object", "properties": { "city": { "type": "string" }, "street": { "type": "string" }, "location": { "type": "object", "properties": { "latitude": { "type": "number" }, "longitude": { "type": "number" } }, "required": ["latitude", "longitude"] } }, "required": ["city", "street"] },
        "instructions": { "type": "string", "description": "可选配送备注。" }
      }, "required": ["address"]
    }
  },
  "required": ["orderNo", "items", "customer"]
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "用例 03 · 根数组与多维数组",
  "description": "根值不是对象而是数组；包含数组套数组、数组套对象、嵌套枚举数组。",
  "type": "array",
  "items": {
    "type": "object",
    "properties": {
      "name": { "type": "string", "description": "数据组名称。" },
      "matrix": { "type": "array", "description": "二维数值矩阵。", "items": { "type": "array", "items": { "type": "number" } } },
      "cube": { "type": "array", "description": "三维整数数组。", "items": { "type": "array", "items": { "type": "array", "items": { "type": "integer" } } } },
      "groups": {
        "type": "array", "items": {
          "type": "object", "properties": {
            "key": { "type": "string" },
            "rows": { "type": "array", "items": { "type": "object", "properties": { "active": { "type": "boolean" }, "states": { "type": "array", "items": { "type": "string", "enum": ["new", "valid", "invalid"] } } }, "required": ["active"] } }
          }, "required": ["key", "rows"]
        }
      }
    },
    "required": ["name", "matrix"]
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "用例 04 · 字典与特殊类型映射",
  "description": "动态键字典以及 bigint/bytes 的 JSON 表示示例；它们不是原生 Map、bigint、Uint8Array 的反射声明。",
  "type": "object",
  "properties": {
    "labelsByKey": {
      "type": "object", "description": "固定的分组信息和自定义标签保存在同一个对象中。",
      "properties": {
        "groupName": { "type": "string", "description": "固定字段：标签分组名称。" },
        "version": { "type": "integer", "description": "固定字段：标签分组版本号。" }
      },
      "required": ["groupName"],
      "additionalProperties": { "type": "string", "description": "自定义标签名称对应的文本，例如颜色、尺寸。" },
      "examples": [{ "groupName": "商品标签", "version": 1, "颜色": "红色", "尺寸": "大号" }]
    },
    "productsBySku": {
      "type": "object", "description": "按商品 SKU 保存商品信息。",
      "additionalProperties": { "type": "object", "properties": { "name": { "type": "string" }, "stock": { "type": "integer" }, "prices": { "type": "array", "items": { "type": "number" } } }, "required": ["name", "stock"] }
    },
    "batchesByDate": { "type": "object", "additionalProperties": { "type": "array", "items": { "type": "object", "properties": { "id": { "type": "string" }, "quantity": { "type": "integer" } }, "required": ["id", "quantity"] } }, "description": "按日期保存当日的批次列表。" },
    "bigIntegerText": { "type": "string", "pattern": "^-?(0|[1-9][0-9]*)$", "examples": ["9007199254740993"], "description": "任意精度整数的十进制文本表示，避免 JSON number 精度损失；反射类型仍是 string，不会自动转 bigint。" },
    "binaryBase64": { "type": "string", "contentEncoding": "base64", "contentMediaType": "application/octet-stream", "examples": ["AAECAw=="], "description": "二进制内容的 Base64 文本表示；仍是 string，不会自动转 bytes，注解见原始定义。" },
    "createdAt": { "type": "string", "format": "date-time", "description": "日期时间文本，不引入独立 Date 类型。format 见原文。" },
    "homepage": { "type": "string", "format": "uri", "description": "URI 文本，format 见原文。" },
    "email": { "type": "string", "format": "email", "description": "邮件地址文本，format 见原文。" }
  },
  "required": ["labelsByKey", "bigIntegerText", "binaryBase64"]
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "用例 05 · 联合与条件展示边界",
  "description": "合法 Draft-07 的联合、组合、条件、布尔子模式；用于检查展示边界，不承诺现有业务 Runtime 支持这些特性。",
  "type": "object",
  "properties": {
    "nickname": { "type": ["string", "null"], "description": "可为空文本，类型列显示文本与空值的联合。" },
    "flexibleId": { "anyOf": [{ "type": "string" }, { "type": "integer" }], "description": "anyOf：文本或整数；具体分支见原文。" },
    "payment": {
      "oneOf": [
        { "type": "object", "properties": { "method": { "const": "card" }, "cardLast4": { "type": "string" } }, "required": ["method", "cardLast4"] },
        { "type": "object", "properties": { "method": { "const": "cash" }, "received": { "type": "boolean" } }, "required": ["method", "received"] }
      ], "description": "oneOf：两个支付对象分支；当前树表不伪造统一字段。"
    },
    "bounded": { "type": "number", "allOf": [{ "minimum": 0 }, { "maximum": 100 }], "description": "allOf 组合约束，见原始定义。" },
    "mixedItems": { "type": "array", "items": { "anyOf": [{ "type": "string" }, { "type": "object", "properties": { "value": { "type": "number" } } }] }, "description": "联合元素数组；分支结构查看原文。" },
    "allowedAnything": true,
    "forbiddenField": false,
    "kind": { "type": "string", "enum": ["personal", "company"] },
    "companyName": { "type": "string" }
  },
  "if": { "properties": { "kind": { "const": "company" } }, "required": ["kind"] },
  "then": { "required": ["companyName"] },
  "else": { "not": { "required": ["companyName"] } },
  "required": ["nickname", "kind"]
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "用例 06 · 引用与递归",
  "description": "本地 definitions 复用、递归树与精确文件 ModelRef；当前树表显示引用提示，引用目标查看原文，不无限展开。",
  "type": "object",
  "definitions": {
    "money": { "type": "object", "properties": { "amount": { "type": "number" }, "currency": { "type": "string", "enum": ["CNY", "USD"] } }, "required": ["amount", "currency"] },
    "node": { "type": "object", "properties": { "name": { "type": "string" }, "children": { "type": "array", "items": { "$ref": "#/definitions/node" } } }, "required": ["name"] }
  },
  "properties": {
    "budget": { "$ref": "#/definitions/money", "description": "复用金额值对象；目标见 definitions.money。" },
    "tree": { "$ref": "#/definitions/node", "description": "递归树；不无限展开字段。" },
    "externalStatus": { "$ref": "examples/07-scalar-enum-root.json", "description": "精确 ModelRef 指向另一个已保存的模型，不按所在子目录改写 ID。" }
  },
  "required": ["budget", "tree"]
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "模型登记",
  "description": "管理模型的名称、说明、所属包、包名称、标签与模型存储方式。代码内置定义由系统直接提供；持久化定义通过存储 ID 与模型 ID 读取。",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "modelRef",
    "storage"
  ],
  "properties": {
    "modelRef": {
      "type": "string",
      "minLength": 1,
      "pattern": "\\S",
      "description": "模型的稳定 ID，与 Runtime 使用的 ModelRef 一致；读取模型定义时也以此值作为 Store 内的记录 ID。项目内不得重复登记。"
    },
    "name": {
      "type": "string",
      "minLength": 1,
      "pattern": "\\S",
      "description": "管理侧显示名称。未设置时使用模型定义中的 title；定义没有 title 时使用 modelRef。"
    },
    "description": {
      "type": "string",
      "description": "管理侧说明。未设置时使用模型定义中的 description；显式空字符串表示不显示说明。"
    },
    "package": {
      "type": "string",
      "minLength": 1,
      "pattern": "\\S",
      "description": "模型所属包的稳定标识，例如 memsphere.builtin、memsphere.examples.orders。省略表示未定义包；本项目也可有自己的包。",
      "examples": [
        "memsphere.builtin",
        "memsphere.examples.orders",
        "acme.commerce"
      ]
    },
    "package_name": {
      "type": "string",
      "minLength": 1,
      "pattern": "\\S",
      "description": "所属包的显示名称，例如 Memsphere 内置、订单示例。仅在设置 package 时填写；未设置时显示 package。同一个包的模型可重复保存名称，名称应保持一致。"
    },
    "tags": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1,
        "pattern": "\\S"
      },
      "description": "辅助分类标签，例如 example、experimental。一个模型可以有多个标签，同一条记录中的标签不得重复。"
    },
    "storage": {
      "type": "string",
      "enum": [
        "builtin",
        "store"
      ],
      "description": "模型存储方式：builtin 为代码内置，由系统直接提供定义；store 为持久化存储，必须同时填写 store_id。此字段不表示包的来源。"
    },
    "store_id": {
      "type": "string",
      "minLength": 1,
      "pattern": "\\S",
      "description": "保存模型定义的 Store ID。storage 为 store 时必填，以 store_id 与 modelRef 读取定义；storage 为 builtin 时不得填写。不得另存重复的定义 ID。"
    }
  },
  "examples": [
    {
      "modelRef": "sales/order.json",
      "name": "订单",
      "package": "myproject.orders",
      "package_name": "订单管理",
      "tags": [
        "order"
      ],
      "store_id": "models/json-schema/draft-07",
      "storage": "store"
    },
    {
      "modelRef": "memsphere/run/artifact",
      "name": "运行产物",
      "package": "memsphere.builtin",
      "package_name": "Memsphere 内置",
      "tags": [
        "run",
        "artifact"
      ],
      "storage": "builtin"
    },
    {
      "modelRef": "notes.json",
      "name": "备注",
      "tags": [
        "example"
      ],
      "store_id": "models/json-schema/draft-07",
      "storage": "store"
    }
  ]
}
